package com.afterglow.player;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.*;import android.view.*;import java.io.*;import java.util.*;
public class VisualChecks extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();PlaybackService s=null;MainActivity ui=null;ArrayList<Track> library=null,next=null;int selected=0;boolean repeat=false;try{ui=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));for(int i=0;i<50&&PlaybackService.instance==null;i++)Thread.sleep(100);s=PlaybackService.instance;if(s==null)throw new Exception("No playback service");final PlaybackService p=s;final MainActivity a=ui;library=new ArrayList<>(p.queue);next=new ArrayList<>(p.upcoming);selected=p.index;repeat=p.repeat;
 runOnMainSync(()->{p.pause(true);p.releasePlayer();p.upcoming.clear();p.queue.clear();p.index=0;p.repeat=false;p.queue.add(new Track("Original demo","Afterglow","demo","local"));for(int i=0;i<100;i++)p.queue.add(new Track("Library song "+i,"Artist",i==0?"demo":"",i==0?"local":"query"));p.play(0);a.page=0;a.render();a.getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);a.visual.mode=0;});Thread.sleep(1800);if(!p.playing())throw new Exception("Demo not playing");VisualView v=a.visual;long before=v.drawnFrames;Thread.sleep(3000);long frames=v.drawnFrames-before;if(frames<120)throw new Exception("Record below 40 FPS: "+frames+" frames in 3 seconds");result.putLong("record_frames_in_3_seconds",frames);Bitmap screenshot=getUiAutomation().takeScreenshot();if(screenshot!=null)try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getExternalFilesDir(null),"record-ui.png"))){screenshot.compress(Bitmap.CompressFormat.PNG,100,out);}
 runOnMainSync(()->{p.enqueue(p.queue.get(1),false);a.showQueue();});Thread.sleep(500);screenshot=getUiAutomation().takeScreenshot();if(screenshot!=null)try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getExternalFilesDir(null),"queue-ui.png"))){screenshot.compress(Bitmap.CompressFormat.PNG,100,out);}runOnMainSync(()->a.queueDialog.dismiss());result.putString("result","PASS: smooth record rendering with 100 library songs; record and queue UI screenshots");
 }catch(Throwable e){result.putString("failure",e.toString());}finally{if(s!=null&&library!=null){final PlaybackService p=s;final ArrayList<Track> saved=library,upcoming=next;final int at=selected;final boolean r=repeat;runOnMainSync(()->{p.pause(true);p.releasePlayer();p.queue.clear();p.queue.addAll(saved);p.upcoming.clear();p.upcoming.addAll(upcoming);p.index=at;p.repeat=r;p.save();});}if(ui!=null){final MainActivity a=ui;runOnMainSync(()->a.render());}finish(result.containsKey("failure")?Activity.RESULT_CANCELED:Activity.RESULT_OK,result);}}
}
